class Pet {
 const Pet({required this.id,required this.name,required this.species,this.breed='',this.birthDate='',this.ageEstimated=false,this.sex='',this.weightValue,this.weightUnit='lb',this.photoPath='',this.adoptionDate='',this.notes='',this.vetName='',this.vetPhone='',this.archived=false});
 final String id,name,species,breed,birthDate,sex,weightUnit,photoPath,adoptionDate,notes,vetName,vetPhone; final double? weightValue; final bool ageEstimated,archived;
 Map<String,Object?> toMap()=>{'id':id,'name':name,'species':species,'breed':breed,'birthDate':birthDate,'ageEstimated':ageEstimated?1:0,'sex':sex,'weightValue':weightValue,'weightUnit':weightUnit,'photoPath':photoPath,'adoptionDate':adoptionDate,'notes':notes,'vetName':vetName,'vetPhone':vetPhone,'archived':archived?1:0};
 factory Pet.fromMap(Map<String,Object?> m)=>Pet(id:m['id'] as String,name:m['name'] as String,species:m['species'] as String,breed:m['breed'] as String? ?? '',birthDate:m['birthDate'] as String? ?? '',ageEstimated:m['ageEstimated']==1,sex:m['sex'] as String? ?? '',weightValue:(m['weightValue'] as num?)?.toDouble(),weightUnit:m['weightUnit'] as String? ?? 'lb',photoPath:m['photoPath'] as String? ?? '',adoptionDate:m['adoptionDate'] as String? ?? '',notes:m['notes'] as String? ?? '',vetName:m['vetName'] as String? ?? '',vetPhone:m['vetPhone'] as String? ?? '',archived:m['archived']==1);
 Pet copyWith({String? name,String? species,String? breed,String? birthDate,String? sex,double? weightValue,String? weightUnit,String? photoPath,String? adoptionDate,String? notes,String? vetName,String? vetPhone,bool? archived})=>Pet(id:id,name:name??this.name,species:species??this.species,breed:breed??this.breed,birthDate:birthDate??this.birthDate,ageEstimated:ageEstimated,sex:sex??this.sex,weightValue:weightValue??this.weightValue,weightUnit:weightUnit??this.weightUnit,photoPath:photoPath??this.photoPath,adoptionDate:adoptionDate??this.adoptionDate,notes:notes??this.notes,vetName:vetName??this.vetName,vetPhone:vetPhone??this.vetPhone,archived:archived??this.archived);
}
